using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.SGR.MenusBotones;using GraphApi.Services.SGR.MenusBotones;namespace GraphApi.Controllers.SGR.MenusBotones{    /// <summary>    /// Gestión de MenusBotones: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("SGR/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre MenusBotones")]    public class MenusBotonesController : Controller    {        private readonly IMenusBotonesService _objService;        public MenusBotonesController(IMenusBotonesService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los MenusBotones, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="menuBotonID">MenuBotonID</param>        /// <param name="menuID">MenuID</param>        /// <param name="tituloMenu">TituloMenu</param>        /// <param name="boton">Boton</param>        /// <param name="accion">Accion</param>        /// <param name="orden">Orden</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de MenusBotones</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar MenusBotones",            Description = "Devuelve MenusBotones aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadMenusBotones>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadMenusBotones>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? menuBotonID,            [FromQuery] int? menuID,            [FromQuery] string? tituloMenu,            [FromQuery] string? boton,            [FromQuery] string? accion,            [FromQuery] int? orden,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetMenusBotonesDynamic(                menuBotonID,                 menuID,                 tituloMenu,                 boton,                 accion,                 orden,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo MenusBotone.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del MenusBotone a crear.</param>        /// <returns>El MenusBotone recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear MenusBotones",            Description = "Inserta un nuevo MenusBotone en la base de datos."        )]        [ProducesResponseType(typeof(clReadMenusBotones), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadMenusBotones>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateMenusBotones objInput)        {            var vCreated = await _objService.CreateMenusBotones(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de MenusBotone.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del MenusBotone.</param>        /// <returns>El MenusBotone actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar MenusBotones",            Description = "Actualiza uno o varios campos de MenusBotone existente."        )]        [ProducesResponseType(typeof(clReadMenusBotones), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadMenusBotones>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateMenusBotones objInput)        {            var vUpdated = await _objService.UpdateMenusBotones(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un MenusBotone por su ID.        /// </summary>        [HttpDelete("{nMenusBotonesID:int}")]        [SwaggerOperation(            Summary = "Eliminar MenusBotone",            Description = "Borra un MenusBotone si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nMenusBotonesID)        {            var success = await _objService.DeleteMenusBotones(nMenusBotonesID);            return success ? NoContent() : NotFound();        }    }}